import manifest from '../../content/chess/levels.json';
import { selectDailyChessPuzzle, rowToPuzzle } from './chessDaily';
import { LAUNCH_DATE, getTodayDateString } from './dailySelector';

// Target puzzle ratings, generated by content-engine/build_chess_levels.py.
export const CHESS_LEVELS = manifest.levels.map((entry) => entry.level);
export const DEFAULT_CHESS_LEVEL = 1000;

export function isChessLevel(level) {
  return CHESS_LEVELS.includes(level);
}

export function getChessLevelName(level) {
  if (level < 800) return 'Principiante';
  if (level < 1400) return 'Básico';
  if (level < 1800) return 'Intermedio';
  if (level < 2200) return 'Avanzado';
  return 'Experto';
}

// One request per level per session; each file is ~100 KB and holds 730 puzzles.
const levelCache = new Map();

function loadChessLevel(level) {
  if (!levelCache.has(level)) {
    const request = fetch(`${import.meta.env.BASE_URL}chess/level-${level}.json`)
      .then((response) => {
        if (!response.ok) throw new Error(`No se pudo cargar el nivel ${level}`);
        return response.json();
      })
      .catch((error) => {
        levelCache.delete(level); // let a retry hit the network again
        throw error;
      });
    levelCache.set(level, request);
  }
  return levelCache.get(level);
}

// Same date + same level => same puzzle for everyone.
export async function getDailyChessPuzzle(level, dateStr = getTodayDateString()) {
  const data = await loadChessLevel(level);
  const row = selectDailyChessPuzzle(data.puzzles, dateStr, LAUNCH_DATE);
  return row ? rowToPuzzle(row, level) : null;
}
